INSERT INTO `email_templates` (`id`, `name`, `slug`, `subject`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'WELCOME', 'welcome', 'WELCOME [NAME]!', 'WELCOME [NAME]!\n\nYou have successfully registered on the Shortlet app.', 0, '2020-07-03 08:32:38', '2023-04-21 05:58:13', NULL),
(5, 'FORGOT YOUR PASSWORD!', 'forgot_password', 'test', 'There was a request to change your password!\n\nYours forgot password OTP is: [OTP]', 0, '2022-04-19 05:36:04', '2023-04-21 06:22:45', NULL),
(12, 'Booking Confirmed!', 'checking_form', 'Booking confirmation for Accommodation [PROPERTY_NAME]', 'Dear Sir/Madame,<br>\n									Thank you for your booking request. These are the booking details.', 1, '2022-04-19 05:36:04', '2023-04-21 07:25:11', NULL),
(13, 'Contract Expire', 'contract_expire', 'Contract Expire', 'Contract Expire', 1, '2022-04-19 05:36:04', '2022-10-28 13:18:45', NULL),
(14, 'Welcome', 'host_welcome', 'Host Welcome', 'WELCOME [NAME]!\n\nYou have successfully registered on the Shortlet app. Your login URL is [URL], username: [USERNAME], and password: [PASSWORD]\n\nThank you,\nTeam Shortlet Rental', 1, '2023-01-06 09:50:57', '2023-04-21 06:00:11', NULL),
(15, 'Booking Reservation', 'booking_reservation_confirmed', 'Booking Reservation confirmed [PROPERTY_NAME]', 'Your booking reservation request has been approved. Please pay your booking amount - ([TOTAL_AMOUNT]!). Please click on the link [CHECKOUT]! to pay your booking amount.', 1, '2023-01-09 12:34:00', '2023-04-21 06:00:59', NULL),
(16, 'Sub Admin Welcome', 'sub_admin_welcome', 'Sub Admin Welcome', 'WELCOME [NAME]!\n\nYou have successfully registered on the Shortlet app. Your login URL is [URL], username: [USERNAME], and password: [PASSWORD]\n\nThank you,\nTeam Shortlet Rental', 1, '2023-02-28 11:27:42', '2023-04-21 06:01:25', NULL),
(17, 'Appointment Cancel', 'appointment-cancel', 'Appointment Cancel', 'Dear [NAME]!\n\nThank You for Scheduling an Appointment. But we are not able to confirm your Schedule Appointment. So we are canceling your Appointment. Please schedule another day. \n\nThank you,\nTeam Shortlet Rental', 1, '2023-03-22 06:24:12', '2023-04-21 06:02:20', NULL),
(18, '', '', NULL, NULL, 0, '2023-04-11 13:51:38', NULL, NULL),
(19, 'Booking Rating & Review completed', 'review-completed', 'Booking Rating & Review completed', 'Dear Sir/Madame,\nwe inform you that there is a new review in the rating system. Before it appears on the website, you need to validate it.', 1, '2023-03-27 13:17:59', '2023-04-21 06:02:43', NULL),
(20, 'booking completed', 'booking-completed', 'Booking Completed', 'WELCOME [NAME]!\n\nYou have successfully registered on the Shortlet app. Your login URL is [URL], username: [USERNAME], and password: [PASSWORD]\n\nThank you,\nTeam Shortlet Rental', 0, '2023-03-28 11:54:16', '2023-04-21 06:27:13', NULL),
(21, '', 'Booking-confirmation-Apartment\r\n', NULL, NULL, 0, '2023-03-30 04:50:37', NULL, NULL),
(22, 'Your booking has been ongoing!', 'Ongoing-Booking', 'Booking Ongoing', 'We remind you that your booking is ongoing. we are processing your booking for the following process', 0, '2023-03-30 04:50:44', '2023-04-21 06:27:59', NULL),
(23, 'Your booking has been completed!', 'Completed-Booking', 'Booking Completed\r\n\r\n', 'Dear Sir/Madam, <br> we inform you that your booking No. [Booking_Id] has been completed.', 0, '2023-03-30 04:50:54', '2023-03-30 04:52:01', NULL),
(24, 'Your booking has been canceled!', 'Cancelled-Booking', 'Booking Cancellation', 'We are sorry on this occasion you have not stayed with us and we remind you that your cancellation is by the cancellation policy agreed upon:', 0, '2023-03-30 04:51:03', '2023-04-21 07:29:22', NULL),
(25, 'Your booking is yet to be confirmed!', 'Booking-confirmed-payment-pending', 'booking confirmed - payment pending', 'We remind you that the payment must be made to confirm your booking.', 0, '2023-03-30 04:51:13', '2023-04-21 07:29:58', NULL),
(26, 'Reserve Booking request', 'reserve-book', 'Reserve Booking request [PROPERTY_NAME]', 'Dear Sir/Madame,<br>\n									Thank you your accommodation has been reserved successfully. you will receive an email shortly on the next steps.', 0, '2023-03-30 11:37:28', '2023-04-21 06:06:42', NULL),
(27, 'Your Booking Reservation has been Deny\r\n', 'Booking-Reservation-deny', 'Booking Reservation Deny', 'Your booking reservation request has been denied.\n', 0, '2023-03-30 11:39:43', '2023-04-21 06:07:28', NULL),
(28, 'Booking Confirmed - Pending Payment', 'checking_form', 'Confirm your booking - pending payment [PROPERTY_NAME]', 'Dear Sir/Madame,<br>\n									Your booking is yet to be confirmed. We remind you that the payment must be made in order to confirm your booking. These are the booking details.', 0, '2023-04-11 11:59:46', '2023-04-21 06:07:53', NULL),
(29, 'Host booking payment confirm.', 'Host booking confirm', 'Booking confirmation for Accommodation [PROPERTY_NAME]', 'Dear Sir/Madame,<br>\n									Your booking  has been booked for No of nights- Booking Information:\n', 0, '2023-04-12 10:41:55', '2023-04-21 06:08:29', NULL),
(31, 'Booking Reserved for Accommodation', 'Booking-Reserved-for-Accommodation', 'Booking Reservation for Accommodation  [PROPERTY_NAME]', 'Dear [NAME]<br>\n									Your Accommodation has been reserved for [Number] of nights.  Accept booking if dates are available or deny booking if dates are not available. if you accept the booking request, the guest will receive a notification to make payment within 2 hours. you will receive another email, once the booking has been confirmed for payment.\n', 0, '2023-04-19 10:39:54', '2023-04-21 06:09:36', NULL),
(32, 'Booking Reservation Request Deny.', 'Booking-Reservation-Request-Deny', 'Booking Reservation for Accommodation [PROPERTY_NAME]  has been denied for booking.\n', 'Dear [NAME] <br/> You have denied a request for a guest to book your Accommodation in the city & Area. No of nights- [Number]\n', 0, '2023-04-19 10:40:51', '2023-04-21 06:24:51', NULL),
(33, 'Your booking has been completed!', 'Your-booking-has-been-completed!', 'Booking Completed - Check-out for accommodation [PROPERTY_NAME]', 'Dear [NAME], <br> Guest has been checkout on your Property [PROPERTY_NAME]. Now you are available to take another booking.', 0, '2023-04-19 10:42:07', '2023-04-21 06:11:37', NULL),
(34, 'booking has been cancelled!', 'booking-has-been-cancelled.', 'Booking Cancelled -  [PROPERTY_NAME]', 'Dear [NAME] <br> Your property booking is canceled. Now you are available to take another booking.', 0, '2023-04-19 10:46:43', '2023-04-21 06:12:19', NULL),
(35, 'Host payout email.', 'Host-payout-email', 'Host Payout - [PROPERTY_NAME] ', 'Dear [NAME] <br> we have issued you a payout of [Amount]. This should arrive in your account within 24 hours.', 0, '2023-04-19 10:50:28', '2023-04-21 06:25:01', NULL),
(36, 'Accommodation on Live.', 'accommodation-on-live', 'Accommodation on Live - [PROPERTY_NAME]', 'Open for bookings: congrats, [Name] - your accommodation is now live on our site: we are happy to welcome you as an official host. Now is the perfect time to make sure you are on track.  Few tips to help you.  Keep your calendar updated.  choose book now or reserve based on your preference.  keep your accommodation clean and amenities in working condition.', 0, '2023-04-19 10:55:02', '2023-04-21 06:14:01', NULL),
(37, 'Sign up', 'registration', 'Thanks for registration', 'Dear [Name], Thank you to start your journey with the short rental. Please verify your account to continue with us.', 0, '2023-04-19 11:08:19', '2023-04-21 06:14:48', NULL),
(38, 'Password Reset.', 'Password-Reset ', 'Password Reset ', 'Copyright Â© 2023 ShortletRental. All rights reserved.', 0, '2023-04-19 11:15:18', '2023-04-21 06:15:22', NULL),
(39, 'Schedule Appointment ', 'schedule-appointment', 'Schedule Appointment', 'Dear [Name]<br>, an appointment is scheduled by [Guest_name].', 0, '2023-04-19 11:23:44', '2023-04-21 06:33:27', NULL);
