INSERT INTO `email_template_lang` (`id`, `email_id`, `name`, `subject`, `description`, `footer`, `lang`, `created_at`, `updated_at`) VALUES
(1, 1, 'HELLO [NAME]!', 'Welcome to the Shortlet Rentals platform', 'Welcome to Shortlet Rentals <br><br>\r\n\r\nCongratulations!!! You have successfully created a guest account. <br><br>\r\n\r\nYou now have all the beautiful accommodation rentals listed on the platform  at your finger tips <br><br>\r\n\r\n\r\n\r\nTake a moment to complete your profile on the website.  <br><br>\r\n\r\nAdd a profile photo, - so we know who you are. <br><br>\r\n\r\nSpecify your gender,- so we can address you properly.  <br><br>\r\n\r\nAdd your date of birth and address - so that we can send you a gift on your birthday. <br><br>\r\n\r\nHappy Booking', 'Copyright Â© 2023 Shortlet Rentals. All rights reserved.', 'en', '2021-01-19 01:30:25', '2023-06-26 00:23:39'),
(31, 12, 'Booking Confirmed !', 'Booking confirmation for Accommodation [PROPERTY_NAME]', 'Dear [NAME],<br>\n									Thank you for making the payment. You\'re one step closer to your trip to [City]', 'Copyright Â© 2023 Shortlet Rental. All rights reserved.', 'en', '2021-01-19 03:52:46', '2023-03-06 00:15:35'),
(32, 13, 'Contract Expire', 'Host Welcome', 'Contract Expire', 'Copyright Â© 2023 Shortlet Rental. All rights reserved.', 'en', '2021-01-19 03:52:46', '2023-02-27 01:06:09'),
(33, 14, 'New Host Registration:', 'Host Registration: Welcome to Shortletrentals.com', 'Dear [NAME], <br>\r\n\r\nCongratulations !!! You have successfully created a host profile  account on Shortletrental.com. A Host specialist will reach out to you within 24 hours to help answer any question you may have before accommodation becomes active.<br/><br/>\r\n \r\nYou are on your way to becoming part of Nigeria\'s largest accommodation platform- and we are glad to have you here.<br/><br/>\r\n\r\nWe know you probably have some questions, so here are a few information to help you get started:<br/><br/>\r\n\r\n\r\nGetting Started:<br/><br/>\r\n\r\nAccess your account :  <br/><br/>\r\n\r\nYour account is where you can continue registering your property, add new properties, or make any changes like price per night, bookable dates, and more.<br/><br/>\r\n\r\nYour login URL is [URL]<br/> username: [USERNAME]<br/> and password: [PASSWORD]<br/>\r\n\r\nStill, have some questions?<br/><br/>\r\n\r\nThe help center helps you with everything- from getting started with our guide to optimizing your presence on the site and getting the most out of shortletrental.com.<br/><br/>\r\n\r\n You can also find the answers to our most frequently asked questions about being a host on shortletrental.com\r\n<br/><br/>\r\nHere is the link to the Help center page: https://shortletrental.com/help-center\r\n<br/>\r\nThank you,\r\n<br/>\r\nShortlet Rentals Team', 'Copyright Â© 2023 Shortlet Rentals. All rights reserved.', 'en', '2023-01-06 09:53:00', '2023-06-26 00:37:18'),
(34, 15, 'Guest Booking Reservation Approved ', 'Booking Reservation request for Accommodation [PROPERTY_NAME] has been approved for booking ', 'Dear [NAME] <br>\n\nYour booking reservation request has been approved. Please make payment for your booking amount - ([TOTAL_AMOUNT]!). Click on the link below to make payment by credit/Debit card [CHECKOUT]!  To Make payment by bank transfer, you will have to make a deposit to Short Let Rentals bank account-Zenith Bank- Account number- 1214818652. Send payment slip via Whatsapp to +234 912 287 7657 or email info@shortletrentals.com. Thank you', 'Copyright Â© 2023 Shortlet Rentals. All rights reserved.', 'en', '2023-01-09 12:35:15', '2023-03-06 00:28:47'),
(35, 16, 'Sub Admin Platform Users', 'Welcome to the Shortlet Rentals Platform', 'WELCOME [NAME]!\r\n<br>\r\nYour account has been successfully created on the Shortlet Rentals platform. Your login URL is [URL], username: [USERNAME], and password: [PASSWORD]\r\n<br>\r\nKindly change your password once you successfully log in. \r\n<br>\r\nTo change your password, click on your name in the top right corner and click on profile.\r\n<br>\r\nWelcome to Shortlet Rentals. We look forward to an amazing time of creating magic together\r\n<br>\r\nThank you,\r\nShortlet Rental Team', 'Copyright Â© 2023 Shortlet Rentals. All rights reserved.', 'en', '2023-02-28 11:27:47', '2023-06-23 05:38:24'),
(36, 17, 'Appointment Cancel', 'Appointment Cancel', 'Dear [NAME]!\n\nThank You for Scheduling an Appointment. But we are not able to confirm your Schedule Appointment. So we are canceling your Appointment. Please schedule another day. \n\nThank you,\nTeam Shortlet Rental', 'Copyright Â© 2023 Shortlet Rentals. All rights reserved.', 'en', '2023-03-22 06:30:24', NULL),
(37, 19, 'Booking Rating & Review completed', 'Booking Rating & Review completed', 'Dear Sir/Madame, <br/>\nWe inform you that there is a new review in the rating system. Before it appears on the website, you need to validate it.', 'Copyright Â© 2023 Shortlet Rentals. All rights reserved.', 'en', '2023-03-27 13:18:51', NULL),
(38, 18, 'Booking Confirmed', 'Booking confirmation for Accommodation [PROPERTY_NAME]', 'Dear Sir/Madame,<br>\n					\nYour Accommodation at city & Area has been booked for [Number] of nights-', 'Copyright Â© 2023 Shortlet Rentals. All rights reserved.', 'en', '2023-03-30 04:53:13', NULL),
(39, 20, 'booking-pending-payment', NULL, NULL, 'Copyright Â© 2023 Shortlet Rentals. All rights reserved.', 'en', '2023-03-30 04:53:29', NULL),
(40, 21, 'Booking-confirmation-Apartment', 'Booking-confirmation-Apartment', NULL, 'Copyright Â© 2023 Shortlet Rentals. All rights reserved.', 'en', '2023-03-30 04:53:49', NULL),
(41, 22, 'Your booking has been ongoing!', 'Booking Ongoing', 'We remind you that your booking is ongoing. we are processing you are looking for the following process', 'Copyright Â© 2023 Shortlet Rentals. All rights reserved.', 'en', '2023-03-30 04:54:12', NULL),
(42, 23, 'Your booking has been completed!', 'Booking Completed: Rate your stay - [PROPERTY_NAME]', 'Dear [NAME], <br> we hope you enjoyed your stay in [PROPERTY_NAME] in [City]. <br><b>Share your opinion by rating the accommodation.</b><br><br>\n[Rate_your_stay]\n', 'Copyright Â© 2023 Shortlet Rentals. All rights reserved.', 'en', '2023-03-30 04:55:02', NULL),
(43, 24, 'Your booking has been canceled!', 'Booking Cancellation', '\nWe are sorry on this occasion you have not stayed with us and we remind you that your cancellation is in accordance with the cancellation policy agreed upon:', 'Copyright Â© 2023 Shortlet Rentals. All rights reserved.', 'en', '2023-03-30 04:55:37', NULL),
(44, 25, 'Your booking is yet to be confirmed!', 'booking confirmed & payment pending', 'We remind you that the payment must be made in order to confirm your booking.', 'Copyright Â© 2023 Shortlet Rentals. All rights reserved.', 'en', '2023-03-30 04:56:01', NULL),
(45, 26, 'Booking Reserved for Accommodation', 'Booking Reservation for Accommodation  [PROPERTY_NAME]', 'Dear [NAME],<br>\n									Thank \nyour accommodation has been reserved successfully. you will receive an email shortly on the next steps.                              If dates are available for booking, the host will accept your request and you will receive another email to make payment. Contact us at +234 9122877657 via Whatsapp or direct call if you have any questions about your booking reservation or email info@shortletrentals.com', 'Copyright Â© 2023 Shortlet Rentals. All rights reserved.', 'en', '2023-03-30 11:40:19', NULL),
(46, 27, 'Your Booking Reservation has been Deny', 'Booking Reservation request for Accommodation [PROPERTY_NAME] has been denied', 'Dear [NAME] <br/> Your reservation request to booking accommodation in the city & area has been denied. You can find other accommodations available for instant bookings here. [Click_Here] to begin your search\n', 'Copyright Â© 2023 Shortlet Rentals. All rights reserved.', 'en', '2023-03-30 11:40:24', NULL),
(47, 28, 'Booking Confirmed - Pending Payment', 'Confirm your booking - pending payment : [PROPERTY_NAME]', 'Dear [NAME]<br>\n									Your booking is yet to be confirmed. We remind you that the payment must be made in order to confirm your booking\n\n', 'Copyright Â© 2023 ShortletRental. All rights reserved.', 'en', '2023-04-11 11:58:36', NULL),
(48, 29, 'Booking Confirmed!', 'Booking confirmation for Accommodation [PROPERTY_NAME]', 'Dear [NAME]<br>\n					\nYour property [PROPERTY_NAME] in [City] phase 1 has been booked by <br> [GUEST_NAME]', 'Copyright Â© 2023 ShortletRental. All rights reserved.', 'en', '2023-04-12 10:42:16', NULL),
(50, 30, 'Booking Reserved for Accommodation', 'Booking Reservation for Accommodation  [PROPERTY_NAME]', 'Dear [NAME]<br>\n									Your Accommodation has been reserved for [Number] of nights.  Accept booking if dates are available or deny booking if dates are not available. if you accept the booking request, the guest will receive a notification to make payment within 2 hours. you will receive another email, once the booking has been confirmed for payment \n', 'Copyright Â© 2023 ShortletRental. All rights reser...', 'en', '2023-04-13 06:48:21', NULL),
(51, 31, 'Booking Reservation Request  Approved', 'Booking Reservation request for Accommodation [PROPERTY_NAME] has been approved for booking ', 'Dear [NAME] <br/>You have accepted the request for a guest to book your accommodation. No of nights : [Number]. <br/> If you want your accommodation to be available for instant bookings. kindly change the booking status in your profile account\n', 'Copyright Â© 2023 ShortletRental. All rights reser...', 'en', '2023-04-13 07:18:19', NULL),
(52, 32, 'Booking Reservation Request Deny', 'Booking Reservation for Accommodation [PROPERTY_NAME]  has been denied for booking', 'Dear [NAME] <br/> You have denied a request for a guest to book your Accommodation in the city & Area. No of nights- [Number]', 'Copyright Â© 2023 Shortlet Rentals. All rights reserved...', 'en', '2023-04-13 09:26:32', '2023-06-22 23:58:02'),
(53, 33, 'Your booking has been completed!', 'Booking Completed - Check-out for accommodation [PROPERTY_NAME]', 'Dear [NAME], <br> Guest has checked out on your Property [PROPERTY_NAME]. Now you are available to take another booking.', 'Copyright Â© 2023 Shortlet Rentals. All rights reser...', 'en', '2023-04-17 11:48:33', '2023-06-22 23:57:29'),
(54, 34, 'booking has been canceled!', 'Booking Canceled -  [PROPERTY_NAME]', 'Dear [NAME] <br> Your property booking is canceled. Now you are available to take another booking.', 'Copyright Â© 2023 Shortlet Rentals. All rights reser...', 'en', '2023-04-17 11:49:29', '2023-06-22 23:56:46'),
(55, 35, 'Host payout email', 'Host Payout - [PROPERTY_NAME]', 'Dear [NAME] <br>, \r\n\r\nWe have issued you a payout of [Amount]. This should arrive in your account within 24 hours.', 'Copyright Â© 2023 Shortlet Rentals. All rights reser...', 'en', '2023-04-19 10:48:03', '2023-06-22 23:56:18'),
(56, 36, 'Your Accommodation Listing  is Live', 'Congrats your Accommodation Listing is Live - [PROPERTY_NAME]', 'Open for bookings: Congrats, <br/>[NAME] <br/> your accommodation is  now live on our site: \r\n\r\nwe are happy to welcome you as an official host. \r\n\r\nNow is the perfect time to make sure you are on track.  \r\n\r\n\r\nFew tips to help you.  \r\n\r\nKeep your calendar updated.  \r\n\r\nChoose Book now or Reserve based on your preference.  \r\n\r\nkeep your accommodation clean and amenities in working condition\r\n\r\nif you have any questions- reach out to your host specialist at +469-684-7374', 'Copyright Â© 2023 Shortlet Rentals. All rights reser...', 'en', '2023-04-19 10:58:13', '2023-06-26 00:21:38'),
(57, 37, 'New partner registration', 'Partner Registration: Welcome to Shortletrentals.com', 'Dear [NAME], <br>\r\n\r\nCongratulations !!! You have successfully created a partner account on Shortletrentals.com. A partner specialist will reach out to you within 24 hours to complete your registration request<br/>\r\n\r\nYou are now part of Nigeria\'s largest accommodation platform- and we are glad to have you here.<br/><br/>\r\n\r\nWe know you probably have some questions, so here are a few information to help you get started:<br/><br/>\r\n\r\nGetting Started:<br/>\r\n\r\nAccess your account: Your account is where you will see all the details about your commission , Promo-code and bookings. <br/><br/>\r\n\r\nGo ahead and update your profile with your profile image and identification card.<br/><br/>\r\n\r\nYour login url is [URL]<br/> username: [USERNAME]<br/> password: [PASSWORD]<br/>\r\n\r\n\r\nStill have some questions?<br/>\r\n\r\nYou can connect with a Partner Specialist via WhatzApp @ +1469-684-7374 \r\nbr/>br/>\r\n\r\nThank you,\r\n<br/>\r\nShortlet Rentals Team', 'Copyright Â© 2023 Shortlet Rentals. All rights reserved...', 'en', '2023-04-19 11:07:03', '2023-06-26 00:23:02'),
(58, 38, 'Password Reset ', 'Password Reset ', 'Password Reset ', 'Copyright Â© 2023 ShortletRental. All rights reser...', 'en', '2023-04-19 11:13:57', NULL),
(59, 39, 'Schedule Appointment ', 'Schedule appointment', 'Dear [NAME],<br> Appointment schedule successfully with shortletrental. Your appointment date [DATE] and [TIME]. Your Location [LOCATION] ', 'Copyright Â© 2023 ShortletRental. All rights reser...', 'en', '2023-04-19 11:17:00', NULL),
(60, 40, 'schedule appointment Reminder', 'Reminder - schedule appointment with in 24 Hours ', 'Dear [NAME] <br>, We are remind you that [Gust_Name] is schedule your appointment within 24 Hours', 'Copyright Â© 2023 ShortletRental. All rights reser...', 'en', '2023-04-19 11:25:07', NULL);
